import { 
  Box, 
  Button, 
  Typography, 
  Card, 
  CardContent, 
  CardMedia, 
  CardActions, 
  Chip,
  TextField,
  IconButton,
  Dialog,
  DialogTitle,
  DialogContent,
  DialogActions
} from '@mui/material';
import { 
  ChatBubbleOutline as CommentIcon,
  Send as SendIcon,
  Edit as EditIcon,
  Delete as DeleteIcon,
  Close as CloseIcon
} from '@mui/icons-material';

const NewsCard = ({ article, showCategory = false, isBreaking = false }) => {
  const { user } = useAuth();
  const [reactions, setReactions] = useState({
    like: 0,
    angry: 0,
    sad: 0,
    support: 0
  });
  const [userReaction, setUserReaction] = useState(null);
  const [isConnected, setIsConnected] = useState(false);
  const [showComments, setShowComments] = useState(false);
  const [comments, setComments] = useState([]);
  const [newComment, setNewComment] = useState('');

  const {
    id,
    title,
    description,
    urlToImage,
    publishedAt,
    source,
    url,
    category
  } = article;

  // Initialize WebSocket connection
  useEffect(() => {
    if (user?.token) {
      webSocketService.connect(user.token);
      setIsConnected(true);

      return () => {
        webSocketService.disconnect();
        setIsConnected(false);
      };
    }
  }, [user]);

  // Subscribe to article updates and listen for comment events
  useEffect(() => {
    if (!isConnected || !id) return;

    // Subscribe to the article
    webSocketService.subscribeToArticle(id);

    // Listen for new comments
    const handleNewComment = (data) => {
      if (data.articleId === id) {
        setComments(prevComments => {
          // Check if comment already exists to prevent duplicates
          if (!prevComments.some(comment => comment.id === data.comment.id)) {
            return [...prevComments, data.comment];
          }
          return prevComments;
        });
      }
    };

    // Listen for comment updates
    const handleCommentUpdated = (data) => {
      if (data.articleId === id) {
        setComments(prevComments =>
          prevComments.map(comment =>
            comment.id === data.comment.id
              ? { ...comment, content: data.comment.content }
              : comment
          )
        );
      }
    };

    // Listen for comment deletions
    const handleCommentDeleted = (data) => {
      if (data.articleId === id) {
        setComments(prevComments =>
          prevComments.filter(comment => comment.id !== data.commentId)
        );
      }
    };

    // Set up all WebSocket listeners
    const unsubscribeNewComment = webSocketService.onNewComment(id, handleNewComment);
    const unsubscribeCommentUpdated = webSocketService.onCommentUpdated(id, handleCommentUpdated);
    const unsubscribeCommentDeleted = webSocketService.onCommentDeleted(id, handleCommentDeleted);

    // Set up reaction update listener
    const unsubscribeReaction = webSocketService.onReactionUpdate(
      id,
      (data) => {
        setReactions(prev => ({
          ...prev,
          [data.type]: data.count || 0
        }));

        if (data.userId === user?.id) {
          setUserReaction(data.type);
        }
      }
    );

    // Initial load of reactions and comments
    const loadInitialData = async () => {
      try {
        // TODO: Replace with actual API call to get initial reactions and comments
        // const response = await api.get(`/api/news/${id}/reactions`);
        // setReactions(response.data.reactions);
        // setUserReaction(response.data.userReaction);
      } catch (error) {
        console.error('Error loading initial data:', error);
      }
    };

    loadInitialData();

    // Cleanup function
    return () => {
      if (unsubscribeNewComment) unsubscribeNewComment();
      if (unsubscribeCommentUpdated) unsubscribeCommentUpdated();
      if (unsubscribeCommentDeleted) unsubscribeCommentDeleted();
      if (unsubscribeReaction) unsubscribeReaction();
    };
  }, [id, isConnected, user?.id]);

  const handleReaction = useCallback((type) => {
    if (!user) return;

    const isSameReaction = userReaction === type;
    const newType = isSameReaction ? null : type;

    // Optimistic update
    setReactions(prev => {
      const newReactions = { ...prev };

      // Remove previous reaction if exists
      if (userReaction) {
        newReactions[userReaction] = Math.max(0, newReactions[userReaction] - 1);
      }

      // Add new reaction if not toggling off
      if (newType) {
        newReactions[newType] = (newReactions[newType] || 0) + 1;
      }

      return newReactions;
    });

    const previousReaction = userReaction;
    setUserReaction(newType);

    // Send reaction to server
    webSocketService.sendReaction(id, newType);

    // Revert on error
    const handleError = () => {
      setUserReaction(previousReaction);
      // Revert reactions state
      setReactions(prev => {
        const reverted = { ...prev };
        if (previousReaction) reverted[previousReaction] = (reverted[previousReaction] || 0) + 1;
        if (newType) reverted[newType] = Math.max(0, (reverted[newType] || 0) - 1);
        return reverted;
      });
    };

    // Simulate error handling (replace with actual API call if needed)
    setTimeout(() => {
      if (!isConnected) {
        handleError();
      }
    }, 5000);

  }, [user, userReaction, id, isConnected]);

  const [editingCommentId, setEditingCommentId] = useState(null);
  const [editingCommentText, setEditingCommentText] = useState('');

  const navigate = useNavigate();

  // Handle comment click - redirect to comment section
  const handleCommentClick = (e) => {
    e.stopPropagation();
    navigate(`/article/${id}/comments`, { state: { article } });
  };

  // Toggle comments section (for in-card comments)
  const toggleComments = (e) => {
    e?.stopPropagation();
    setShowComments(!showComments);
  };

  const handleCommentSubmit = (e) => {
    e.preventDefault();
    if (!newComment.trim() || !user) return;

    const comment = {
      id: Date.now().toString(),
      content: newComment,
      userId: user.id,
      username: user.username || 'Anonymous',
      timestamp: new Date().toISOString()
    };

    // Optimistic update
    setComments(prev => [...prev, comment]);
    setNewComment('');

    // Send comment to server with user ID
    webSocketService.sendComment(id, newComment, user.id);
  };

  const handleEditComment = (commentId) => {
    const comment = comments.find(c => c.id === commentId);
    if (comment) {
      setEditingCommentId(commentId);
      setEditingCommentText(comment.content);
    }
  };

  const handleUpdateComment = (e) => {
    e.preventDefault();
    if (!editingCommentText.trim() || !editingCommentId) return;

    // Optimistic update
    setComments(prev => 
      prev.map(comment => 
        comment.id === editingCommentId 
          ? { ...comment, content: editingCommentText }
          : comment
      )
    );

    // Send update to server
    webSocketService.sendCommentUpdate(id, editingCommentId, editingCommentText);
    
    // Reset editing state
    setEditingCommentId(null);
    setEditingCommentText('');
  };

  const handleDeleteComment = (commentId) => {
    if (!window.confirm('Are you sure you want to delete this comment?')) return;

    // Optimistic update
    setComments(prev => prev.filter(comment => comment.id !== commentId));

    // Send delete to server
    webSocketService.sendCommentDelete(id, commentId);
  };

  const formatDate = (dateString) => {
    try {
      return format(new Date(dateString), 'MMM d, yyyy');
    } catch (e) {
      return '';
    }
  };

  return (
    <div className={`rounded-lg overflow-hidden shadow-md hover:shadow-lg transition-shadow duration-300 bg-white ${isBreaking ? 'border-l-4 border-red-500' : ''}`}>
      {isBreaking && (
        <div className="bg-red-100 text-red-800 px-4 py-1 text-sm font-medium">
          BREAKING
        </div>
      )}
      {article.urlToImage || article.image ? (
        <img
          src={article.urlToImage || article.image}
          alt={title}
          className="w-full h-48 object-cover"
          onError={(e) => {
            e.target.onerror = null;
            e.target.src = 'https://via.placeholder.com/400x200?text=No+Image+Available';
          }}
        />
      ) : (
        <div className="w-full h-48 bg-gray-100 flex items-center justify-center">
          <span className="text-gray-400">No image available</span>
        </div>
      )}
      <div className="p-4">
        <div className="flex justify-between items-center mb-2">
          {showCategory && category && (
            <span className="text-xs font-semibold text-blue-600 bg-blue-100 px-2 py-1 rounded">
              {category}
            </span>
          )}
          {isBreaking && (
            <span className="text-xs font-semibold text-red-600 bg-red-100 px-2 py-1 rounded">
              Breaking
            </span>
          )}
          <span className="text-xs text-gray-500">
            {source?.name && `${source.name} • `}{formatDate(publishedAt)}
          </span>
        </div>
        <h3 className="text-xl font-bold mb-2 line-clamp-2">{title}</h3>
        <p className="text-gray-700 mb-4 line-clamp-3">{description}</p>

        {/* Reaction Buttons */}
        <div className="flex justify-between items-center border-t border-b border-gray-100 py-2 my-3">
          <div className="flex space-x-2">
            {[/* eslint-disable-next-line */
              { type: 'like', emoji: '👍', label: 'Like' },
              { type: 'angry', emoji: '😡', label: 'Angry' },
              { type: 'sad', emoji: '😢', label: 'Sad' },
              { type: 'support', emoji: '❤️', label: 'Support' }
            ].map(({ type, emoji, label }) => (
              <button
                key={type}
                onClick={() => handleReaction(type)}
                className={`flex items-center space-x-1 px-3 py-1.5 rounded-full transition-colors ${
                  userReaction === type
                    ? 'bg-blue-50 text-blue-600'
                    : 'text-gray-600 hover:bg-gray-50'
                }`}
                disabled={!user}
                title={!user ? 'Please login to react' : label}
              >
                <span className="text-lg">{emoji}</span>
                <span className="text-sm font-medium">{reactions[type] || 0}</span>
              </button>
            ))}
          </div>
          <Button 
            startIcon={<CommentIcon />}
            onClick={handleCommentClick}
            sx={{ 
              color: 'text.secondary', 
              '&:hover': { 
                color: 'primary.main',
                backgroundColor: 'rgba(25, 118, 210, 0.04)'
              } 
            }}
          >
            {comments.length} Comments
          </Button>
        </div>

        {/* Comments Section */}
        <div className={`transition-all duration-300 ${showComments ? 'max-h-96' : 'max-h-0 overflow-hidden'}`}>
          <div className="mt-4 space-y-3">
            {comments.length > 0 ? (
              comments.map(comment => (
                <div key={comment.id} className="group flex items-start space-x-3">
                  <div className="flex-shrink-0 w-8 h-8 bg-blue-100 rounded-full flex items-center justify-center text-blue-600 font-medium">
                    {comment.username?.charAt(0).toUpperCase() || 'U'}
                  </div>
                  <div className="flex-1 min-w-0">
                    <div className="flex items-baseline justify-between">
                      <div className="flex items-center">
                        <span className="text-sm font-medium text-gray-900">
                          {comment.username || 'Anonymous'}
                        </span>
                        {comment.userId === user?.id && (
                          <span className="ml-2 text-xs px-1.5 py-0.5 bg-blue-100 text-blue-700 rounded">
                            You
                          </span>
                        )}
                      </div>
                      <span className="text-xs text-gray-500 ml-2 whitespace-nowrap">
                        {formatDate(comment.timestamp)}
                      </span>
                    </div>
                    
                    {editingCommentId === comment.id ? (
                      <form onSubmit={handleUpdateComment} className="mt-1">
                        <div className="flex space-x-2">
                          <input
                            type="text"
                            value={editingCommentText}
                            onChange={(e) => setEditingCommentText(e.target.value)}
                            className="flex-1 border border-gray-300 rounded px-2 py-1 text-sm focus:outline-none focus:ring-1 focus:ring-blue-500"
                            autoFocus
                          />
                          <button
                            type="submit"
                            className="px-2 py-1 text-sm bg-blue-600 text-white rounded hover:bg-blue-700"
                            disabled={!editingCommentText.trim()}
                          >
                            Save
                          </button>
                          <button
                            type="button"
                            onClick={() => {
                              setEditingCommentId(null);
                              setEditingCommentText('');
                            }}
                            className="px-2 py-1 text-sm text-gray-600 hover:text-gray-800"
                          >
                            Cancel
                          </button>
                        </div>
                      </form>
                    ) : (
                      <div className="group-hover:bg-gray-50 -mx-2 px-2 py-1 rounded">
                        <p className="text-sm text-gray-700 mt-0.5">{comment.content}</p>
                        {comment.userId === user?.id && (
                          <div className="flex space-x-2 mt-1 opacity-0 group-hover:opacity-100 transition-opacity">
                            <button
                              onClick={() => handleEditComment(comment.id)}
                              className="text-xs text-blue-600 hover:text-blue-800"
                            >
                              Edit
                            </button>
                            <button
                              onClick={() => handleDeleteComment(comment.id)}
                              className="text-xs text-red-600 hover:text-red-800"
                            >
                              Delete
                            </button>
                          </div>
                        )}
                      </div>
                    )}
                  </div>
                </div>
              ))
            ) : (
              <p className="text-sm text-center text-gray-500 py-3">No comments yet. Be the first to comment!</p>
            )}
          </div>

          {/* Add Comment Form */}
          {user ? (
            <form onSubmit={handleCommentSubmit} className="mt-4 pt-3 border-t border-gray-100">
              <div className="flex space-x-2">
                <input
                  type="text"
                  value={newComment}
                  onChange={(e) => setNewComment(e.target.value)}
                  placeholder="Write a comment..."
                  className="flex-1 border border-gray-300 rounded-lg px-3 py-2 text-sm focus:outline-none focus:ring-2 focus:ring-blue-500 focus:border-transparent"
                />
                <button
                  type="submit"
                  disabled={!newComment.trim()}
                  className="bg-blue-600 text-white px-4 py-2 rounded-lg text-sm font-medium hover:bg-blue-700 focus:outline-none focus:ring-2 focus:ring-blue-500 focus:ring-offset-1 disabled:opacity-50 disabled:cursor-not-allowed transition-colors whitespace-nowrap"
                >
                  Post
                </button>
              </div>
            </form>
          ) : (
            <div className="text-center py-3 border-t border-gray-100 mt-3">
              <p className="text-sm text-gray-500">
                Please <a href="/login" className="text-blue-600 hover:underline font-medium">login</a> to comment
              </p>
            </div>
          )}
        </div>

        <div className="flex justify-between items-center mt-4 pt-3 border-t border-gray-100">
          <div className="text-sm text-gray-500">
            {source?.name || 'News Service'}
          </div>
          <a
            href={url}
            target="_blank"
            rel="noopener noreferrer"
            className="text-blue-600 hover:text-blue-800 text-sm font-medium flex items-center hover:underline"
          >
            Read more
            <svg xmlns="http://www.w3.org/2000/svg" className="h-4 w-4 ml-1" fill="none" viewBox="0 0 24 24" stroke="currentColor">
              <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M9 5l7 7-7 7" />
            </svg>
          </a>
        </div>
      </div>
    </div>
  );
};
export default NewsCard;
